def build_next(pattern):
    n = len(pattern)
    nxt = [0] * n
    k = 0
    for i in range(1, n):
        while k > 0 and pattern[i] != pattern[k]:
            k = nxt[k - 1]
        if pattern[i] == pattern[k]:
            k += 1
        nxt[i] = k
    return nxt

def kmp_index(text, pattern):
    if len(pattern) == 0:
        return 0
    nxt = build_next(pattern)
    j = 0
    for i in range(len(text)):
        while j > 0 and text[i] != pattern[j]:
            j = nxt[j - 1]
        if text[i] == pattern[j]:
            j += 1
        if j == len(pattern):
            return i - len(pattern) + 1
    return -1

print(kmp_index('ababcabcacbab', 'abc'))
print(kmp_index('aaabaaaab', 'aaaab'))
print(build_next('abab'))
print(build_next('aaaab'))
print(kmp_index('abc', ''))
